GOVERNANCE_FIELDS = ['purpose', 'data_categories', 'owner', 'approved_users',
                    'retention_rule', 'human_review', 'incident_contact']

def governance_readiness(record):
    missing = [field for field in GOVERNANCE_FIELDS if not record.get(field)]
    return {'ready_for_review': not missing, 'missing': missing}
